begin;
select plan(32);
-- Reserved distant fixture range avoids the user's current agenda; never delete
-- unrelated applications to manufacture an empty day/month for these assertions.
do $guard$ begin
 if exists(select 1 from public.medication_applications where scheduled_at>='2096-11-01T00:00:00Z' and scheduled_at<'2097-01-01T00:00:00Z') then
  raise exception 'agenda fixture range is occupied; choose another empty range';
 end if;
end $guard$;
insert into auth.users(id) values ('59000000-0000-4000-8000-000000000001'),('59000000-0000-4000-8000-000000000002');
insert into auth.sessions(id,user_id) values ('69000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000001'),('69000000-0000-4000-8000-000000000002','59000000-0000-4000-8000-000000000002');
insert into public.staff_members(user_id,active) values ('59000000-0000-4000-8000-000000000001',true),('59000000-0000-4000-8000-000000000002',true);
insert into public.animals(id,name,species,sex,size,approximate_age) values ('79000000-0000-4000-8000-000000000001','Fixture agenda','dog','female','small','2');
create temporary table agenda_test(kind text,value jsonb);grant all on agenda_test to authenticated;
select set_config('request.jwt.claims','{"sub":"59000000-0000-4000-8000-000000000001","session_id":"69000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
insert into agenda_test select 'saved',public.save_medication_treatment(repeat('q',32),'{"animal_id":"79000000-0000-4000-8000-000000000001","medication_name":"Agenda","schedule_mode":"interval","starts_on":"2096-11-01","starts_time":"22:20","ends_on":"2096-11-02","ends_time":"00:01","fixed_times":[],"interval_minutes":1}');
-- 100 on November 1, two on November 2; a second treatment supplies simultaneous time.
insert into agenda_test select 'saved2',public.save_medication_treatment(repeat('r',32),'{"animal_id":"79000000-0000-4000-8000-000000000001","medication_name":"Simultânea","schedule_mode":"fixed_times","starts_on":"2096-11-01","starts_time":"22:20","ends_on":"2096-11-01","ends_time":"23:00","fixed_times":["22:20"]}');
insert into agenda_test select 'month',public.get_medication_calendar_month('2096-11');
select is((select value->>'timezone' from agenda_test where kind='month'),'America/Sao_Paulo','server timezone explicit');
select is((select (value->'days'->0->>'pending')::int from agenda_test where kind='month'),101,'month counts full day without pagination truncation');
select is((select (value->'days'->1->>'pending')::int from agenda_test where kind='month'),2,'midnight follows civil shelter date');
select is(jsonb_array_length(public.get_medication_calendar_month('2096-12')->'days'),0,'empty month');
insert into agenda_test select 'day',public.list_medication_day('2096-11-01',null);
select is((select jsonb_array_length(value->'items') from agenda_test where kind='day'),100,'first page limited to 100');
select ok((select octet_length(value->>'next_cursor') between 1 and 1024 from agenda_test where kind='day'),'cursor bounded');
select is((select value->'items'->0->>'scheduled_local_time' from agenda_test where kind='day'),'22:20','civil time from server not UTC date');
select is((select value->'items'->0->>'scheduled_local_date' from agenda_test where kind='day'),'2096-11-01','civil day preserved');
select ok((select value->'items'->0->>'id'<value->'items'->1->>'id' from agenda_test where kind='day'),'simultaneous sorted by UUID');
insert into agenda_test select 'next',public.list_medication_day('2096-11-01',(select value->>'next_cursor' from agenda_test where kind='day'));
select is((select jsonb_array_length(value->'items') from agenda_test where kind='next'),1,'last page remainder');
select ok((select value->>'next_cursor' is null from agenda_test where kind='next'),'last page terminates');
select is((select count(distinct item->>'id')::int from agenda_test cross join lateral jsonb_array_elements(value->'items') item where kind in ('day','next')),101,'all pages without duplicate or omission');
select is(jsonb_array_length(public.list_medication_day('2096-11-03',null)->'items'),0,'empty day');
select throws_ok($$select public.list_medication_day('2096-11-02',(select value->>'next_cursor' from agenda_test where kind='day'))$$,'22023','invalid_payload','cursor bound to day');
select throws_ok($$select public.list_medication_day('2096-11-01',repeat('a',1025))$$,'22023','invalid_payload','oversize cursor denied');
select throws_ok($$select public.list_medication_day('2096-11-01','invalid')$$,'22023','invalid_payload','malformed cursor denied');
select throws_ok($$select public.get_medication_calendar_month('2096-13')$$,'22023','invalid_payload','invalid month denied');
select throws_ok($$select public.list_medication_day('2096-02-30',null)$$,'22023','invalid_payload','invalid day denied');
select is(jsonb_array_length(public.get_medication_application_history((select (value->'items'->0->>'id')::uuid from agenda_test where kind='day'),null)->'items'),0,'unperformed application has empty history');
select throws_ok($$select public.get_medication_application_history('99000000-0000-4000-8000-000000000001',null)$$,'PT404','not_found','unknown application not found');
select set_config('request.jwt.claims','{"sub":"59000000-0000-4000-8000-000000000002","session_id":"69000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.list_medication_day('2096-11-01',(select value->>'next_cursor' from agenda_test where kind='day'))$$,'22023','invalid_payload','cursor bound to actor');
select set_config('request.jwt.claims','{"sub":"59000000-0000-4000-8000-000000000001","session_id":"69000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
update private.medication_agenda_state set agenda_version=agenda_version+1 where singleton;
set local role authenticated;
select throws_ok($$select public.list_medication_day('2096-11-01',(select value->>'next_cursor' from agenda_test where kind='day'))$$,'PT409','snapshot_changed','mutation rejects old snapshot');
reset role;
update public.medication_applications set state='cancelled',cancelled_at=now(),cancelled_reason='treatment_stopped' where id=(select (value->'items'->1->>'id')::uuid from agenda_test where kind='day');
update public.medication_applications set state='completed',version=102,performed_by='59000000-0000-4000-8000-000000000001',performed_at='2096-11-02T01:30:00Z' where id=(select (value->'items'->0->>'id')::uuid from agenda_test where kind='day');
insert into public.medication_application_events(application_id,event_type,actor_id,actor_label,occurred_at,application_version,reason,snapshot)
select (select (value->'items'->0->>'id')::uuid from agenda_test where kind='day'),case when i%2=0 then 'completed' else 'completion_reversed' end,'59000000-0000-4000-8000-000000000001','Equipe original','2096-11-02T01:30:00Z',i,case when i%2=1 then 'Correção de teste' end,'{}'::jsonb from generate_series(2,102) i;
set local role authenticated;
select is((public.get_medication_calendar_month('2096-11')->'days'->0->>'cancelled')::int,1,'cancelled included separately in month');
select is((public.get_medication_calendar_month('2096-11')->'days'->0->>'completed')::int,1,'completed counted separately');
insert into agenda_test select 'history',public.get_medication_application_history((select (value->'items'->0->>'id')::uuid from agenda_test where kind='day'),null);
select is((select jsonb_array_length(value->'items') from agenda_test where kind='history'),100,'history first page bounded');
insert into agenda_test select 'history2',public.get_medication_application_history((select (value->'items'->0->>'id')::uuid from agenda_test where kind='day'),(select value->>'next_cursor' from agenda_test where kind='history'));
select is((select jsonb_array_length(value->'items') from agenda_test where kind='history2'),1,'history last page remainder');
select is((select (value->'items'->0->>'application_version')::int from agenda_test where kind='history2'),102,'history order by application version');
select throws_ok($$select public.get_medication_application_history((select (value->'items'->1->>'id')::uuid from agenda_test where kind='day'),(select value->>'next_cursor' from agenda_test where kind='history'))$$,'22023','invalid_payload','history cursor bound to application');
reset role;
update public.staff_members set active=false where user_id='59000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_medication_calendar_month('2096-11')$$,'42501','staff_required','revoked staff denied');
reset role;
set local role anon;
select throws_ok($$select public.get_medication_calendar_month('2096-11')$$,'42501',null,'visitor month denied');
select throws_ok($$select public.list_medication_day('2096-11-01',null)$$,'42501',null,'visitor agenda denied');
select throws_ok($$select public.get_medication_application_history('99000000-0000-4000-8000-000000000001',null)$$,'42501',null,'visitor history denied');
reset role;
select * from finish();rollback;
